"""Explain instrumentation, atomicity and directional memory ordering."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1561': ('도서관에서 책을 꺼낼 때 확인 기록을 남기는 길과 특별한 사정으로 그 단계를 거치지 않는 길이 있다고 생각해 봅시다. 길이 다르다고 책의 페이지 순서가 바뀌지는 않아요.', '계측 단계를 거치는지와 메모리 접근 순서를 구별합니다.', 'atomic_long_read → instrument_atomic_read → raw_atomic_long_read의 호출 흐름을 적으세요. raw 읽기의 순서 약속은 relaxed라고 옆에 적으세요.', ['계측은 프로그램이 무슨 일을 하는지 검사할 수 있도록 확인 단계를 넣는 일이에요. instrumentation이라는 영어도 이 뜻으로 쓰여요. 어떤 확인 작업이 실제로 들어가는지는 커널 설정에 따라 달라질 수 있어요.', '일반 atomic_long_read의 본문에는 먼저 instrument_atomic_read를 부르고, 다음에 raw_atomic_long_read를 부르는 흐름이 있어요. 바깥 함수가 검사 지점을 거친 뒤 실제 읽기를 안쪽 함수에 맡기는 모습이에요.', 'raw_atomic_long_read는 이 바깥 계측 단계를 거치지 않는 경로예요. 이어서 커널 설정에 맞는 원자 연산 함수를 불러요. raw라는 글자가 숫자의 비트 수나 주변 접근 순서를 저절로 바꾸지는 않아요.', 'noinstr은 이런 계측이 들어가면 안 되는 특별한 코드 영역을 나타내는 말이에요. 원문 주석은 raw 함수를 그 영역에서 사용할 수 있다고 설명해요. 그렇다고 아무 코드에서나 raw를 고르는 것이 권장된다는 뜻은 아니에요.', '주석은 그 밖의 일반 코드에서는 atomic_long_read 같은 atomic_long 계열을 선호하라고 해요. 그래서 먼저 일반 API를 보고, 특별한 영역의 요구가 있을 때 raw 사용 조건을 확인해야 해요. API는 다른 코드가 기능을 부르는 약속된 입구라는 뜻이에요.', '메모리 접근 순서는 별도로 읽어야 해요. raw_atomic_long_read는 relaxed이고 raw_atomic_long_read_acquire는 acquire예요. raw면 무조건 full ordering이거나 항상 더 빠르다는 결론은 낼 수 없어요. 호출 흐름을 읽은 것과 실제 커널의 계측·성능을 실행 검사한 것도 구별해요.'], [('함수 이름 앞에 raw가 붙으면 모든 메모리 접근에 full ordering이 자동으로 생기나요?', ['네. raw가 붙으면 뒤의 순서 이름은 중요하지 않아요', '아니요. raw 여부와 각 함수의 순서 약속은 별개예요'], '정답은 두 번째예요. raw_atomic_long_read도 relaxed 읽기예요. 계측 경로를 고르는 일과 주변 메모리 접근 순서를 고르는 일을 섞으면 안 돼요.'), ('특별한 noinstr 영역 밖의 일반 코드에서 주석이 권하는 것은 무엇인가요?', ['atomic_long 계열 함수를 먼저 사용하는 것이에요', '언제나 raw_atomic_long 계열만 쓰는 것이에요'], '정답은 첫 번째예요. 주석은 noinstr에서 raw를 쓸 수 있다고 하고, 다른 곳에서는 일반 계열을 선호하라고 해요. 특별한 허용을 모든 곳의 권장으로 바꿔 읽지 마세요.')]), 'os1562': ('숫자판에 1을 더하는 일을 한 묶음으로 처리하는 규칙과, 다른 게시판의 내용을 언제 볼 수 있는지 정하는 규칙은 서로 달라요.', '숫자 하나의 원자적 갱신과 다른 주소의 접근 순서를 구별합니다.', '숫자판 0에 두 사람이 각각 원자적으로 1을 더한다고 그리세요. 두 연산 뒤 2가 되는 그림 옆에 “다른 게시판 내용의 공개 순서는 별도”라고 적으세요.', ['RMW는 Read·Modify·Write의 머리글자예요. 값을 읽고, 계산해서 바꾸고, 결과를 쓰는 일이에요. 예를 들어 원자적 더하기는 이 흐름을 다른 원자적 갱신이 중간에 끼어들 수 없는 한 연산으로 다뤄요.', '다른 갱신이 없고 범위 초과도 없는 숫자판 0에 두 사람이 각각 원자적으로 1을 더하면, 둘 다 끝난 뒤 값은 2예요. 한 사람이 0에서 1로, 다음 사람이 1에서 2로 바꾸는 순서로 이해할 수 있어요.', '반대로 두 사람이 따로 0을 읽고 각각 나중에 1을 쓰면 마지막 값이 1일 수 있어요. 두 번 더하려던 뜻이 사라지지요. relaxed RMW는 이런 식으로 읽기와 쓰기를 제각각 해도 된다는 뜻이 아니에요.', 'relaxed 또는 unordered는 여기서 다른 메모리 위치에 대한 추가 순서 보장이 없다는 뜻이에요. 숫자판 갱신은 원자적이지만 다른 주소의 게시판 내용까지 준비됐다는 약속은 그 이름만으로 얻을 수 없어요.', '기본 규칙도 구별해야 해요. 단순 읽기·쓰기나 값을 반환하지 않는 RMW는 기본적으로 다른 주소에 대한 순서 보장이 없어요. 값을 반환하는 RMW는 기본적으로 full ordering이지만, _relaxed 같은 명시적 형태와 조건부 연산의 실패에는 다른 규칙이 있어요.', '원자 연산을 두 번 호출했다고 두 호출 전체가 하나의 원자 연산이 되지는 않아요. 여러 숫자판의 상태를 함께 맞추는 일도 별도예요. 작은 숫자 예시가 맞는 것은 계산 이해에 도움이 되지만 여러 CPU의 메모리 순서를 검증했다는 증거는 아니에요.'], [('relaxed RMW라면 숫자판 갱신도 읽기와 쓰기로 흩어져 원자성이 없어지나요?', ['네. relaxed라서 다른 갱신이 중간에 끼어들어도 돼요', '아니요. 원자적 갱신은 유지되고 다른 주소의 순서 약속이 약한 것이에요'], '정답은 두 번째예요. 숫자 하나를 원자적으로 바꾸는 규칙과 다른 자료를 읽고 쓰는 순서 규칙을 나눠 보세요. relaxed도 원자 연산이에요.'), ('문서에서 unordered라고 할 때 무엇에 대한 설명인가요?', ['다른 메모리 위치와의 접근 순서예요', '숫자를 담는 비트 수가 정해지지 않았다는 뜻이에요'], '정답은 첫 번째예요. 주소는 자료가 놓인 위치예요. 다른 위치와 어떤 순서로 읽고 쓰는지의 문제이며, 숫자 칸의 크기를 바꾸는 말이 아니에요.')]), 'os1563': ('답안 내용을 먼저 적고 “준비 끝” 표시를 붙여요. 읽는 사람은 그 표시를 확인한 뒤 답안을 봐야 해요. 표시를 쓰는 쪽과 읽는 쪽의 순서 약속을 짝지어 봅시다.', 'acquire·release가 묶는 방향과 RMW의 읽기·쓰기 부분을 구별합니다.', '작성자: 내용 42 쓰기 → release로 준비=1 쓰기, 독자: acquire로 그 준비=1 확인 → 내용 읽기의 두 줄을 그리세요.', ['RMW를 “읽기 R → 계산 M → 쓰기 W”로 나누어 생각해 봅시다. 실제로는 원자 연산 하나지만, 메모리 접근 순서의 약속을 설명할 때는 읽는 부분과 쓰는 부분을 구별해요.', 'acquire RMW에서 acquire로 지정되는 것은 R, 즉 읽기 부분이에요. 뒤에 하는 메모리 접근이 그 읽기보다 앞으로 넘어가지 않도록 묶는 방향의 약속이에요. 쓰기 부분까지 모든 뒤 접근과 full barrier처럼 묶는다고 넓혀 생각하면 안 돼요.', 'release RMW에서 release로 지정되는 것은 W, 즉 쓰기 부분이에요. 앞서 한 메모리 접근이 그 쓰기 뒤로 넘어가지 않도록 묶는 방향의 약속이에요. acquire와 release는 앞뒤 방향이 달라요.', 'full ordering은 연산 이전과 이후의 접근을 모두 묶는 더 강한 약속이에요. 문서는 연산 앞뒤에 smp_mb라는 메모리 장벽을 둔 것과 같은 순서 계약으로 설명해요. 장벽은 접근 순서를 지키게 하는 규칙이지 다른 CPU가 일을 끝낼 때까지 기다리는 모임 장소가 아니에요.', '답안 공개 예시에서는 먼저 내용 42를 쓰고 release로 준비=1을 공개해요. 읽는 쪽은 acquire로 그 공개된 표시를 확인한 뒤 내용을 읽어요. 서로 상관없는 변수에 release와 acquire를 호출했다고 이 연결이 생기지는 않아요.', '준비 표시를 다시 쓰거나 답안 자료를 지우는 시점도 정해야 해요. acquire를 했다는 이유로 자료가 영원히 유지되지는 않아요. 조건부 원자 연산을 사용한다면 비교 실패 때의 relaxed 규칙도 별도로 확인해야 해요. 이름만 외우기보다 실제로 어떤 값을 관찰했는지 따라가세요.'], [('acquire RMW에서 문서가 acquire라고 지정하는 부분은 어디인가요?', ['읽기와 쓰기 모두 앞뒤 full barrier 두 개와 같아요', 'RMW의 R, 즉 읽기 부분이에요'], '정답은 두 번째예요. acquire는 읽기 부분, release는 쓰기 부분에 붙는 순서 약속이에요. acquire 하나를 앞뒤 모든 접근을 묶는 full ordering과 같다고 읽으면 안 돼요.'), ('full ordering과 acquire는 언제나 같은 약속인가요?', ['아니요. full은 이전과 이후 모두에 더 강한 순서 약속을 줘요', '네. 이름만 다르고 모든 접근 순서는 같아요'], '정답은 첫 번째예요. 같은 숫자를 계산해도 주변 자료의 접근 순서는 다를 수 있어요. acquire의 한쪽 방향 약속과 full의 앞뒤 약속을 구별하세요.')]), 'os1564': ('중요한 작업 바로 앞과 뒤에 순서 표지판을 붙인다고 생각해 봅시다. 표지판과 작업 사이에 다른 일을 끼워 넣으면 표지판의 약속만으로 그 일까지 보호한다고 할 수 없어요.', '원자 RMW의 순서를 보강하는 장벽의 적용 대상과 위치를 이해합니다.', '앞선 접근 A → before_atomic → 원자적 더하기 → after_atomic → 뒤 접근 B를 그리세요. 두 장벽을 더하기 바로 옆에 두고, 사이에 다른 접근을 넣지 마세요.', ['barrier는 메모리 접근 순서를 지키게 하는 장벽이에요. 여기의 smp_mb__before_atomic과 smp_mb__after_atomic은 원자적 RMW, 즉 읽고 계산하고 쓰는 연산의 순서 약속을 보강하는 도구예요.', 'before는 앞이라는 뜻이에요. before_atomic은 앞서 한 접근들을 RMW 자체와 그 뒤 접근들보다 앞에 오도록 묶어요. 그림에서는 A가 원자적 더하기와 그 뒤 작업보다 앞서도록 하는 쪽이에요.', 'after는 뒤라는 뜻이에요. after_atomic은 뒤의 접근들을 RMW 자체와 그 앞 접근들보다 뒤에 오도록 묶어요. 그림에서는 B가 원자적 더하기와 그 앞 작업보다 뒤에 오도록 하는 쪽이에요.', '문서는 장벽과 해당 RMW 사이에 끼운 접근은 그 보강 약속으로 순서가 정해지지 않는다고 설명해요. 그래서 장벽을 RMW 바로 옆에 두라고 권해요. 코드가 위에서 아래로 적혔다는 이유만으로 다른 CPU에도 모든 접근이 그 순서로 보인다고 가정하면 안 돼요.', '이 도구는 단순 read나 set에 아무렇게나 붙여 쓰는 범용 대체 장벽이 아니에요. 문서의 적용 대상은 RMW예요. 기본 full atomic_fetch_add는 before_atomic → relaxed fetch_add → after_atomic과 같은 순서 계약으로 설명되지만 실제 생성 코드나 속도까지 같다는 뜻은 아니에요.', '어떤 CPU 계열은 원자 연산 자체의 순서가 이미 강해서 추가 장벽이 실제 명령을 만들지 않을 수도 있어요. 이를 no-op이라고 해요. 그렇다고 다른 CPU에서도 지워도 된다고 판단할 수 없어요. 이 수업은 원문의 약속과 배치 이유를 읽는 것이며 실제 CPU 성능을 측정한 것은 아니에요.'], [('before_atomic·after_atomic은 문서에서 어떤 연산의 순서를 보강하는 도구인가요?', ['단순 read·set을 포함해 아무 접근에나 같은 약속으로 붙이는 도구예요', '읽기·계산·쓰기를 묶은 원자적 RMW 연산을 위한 도구예요'], '정답은 두 번째예요. 문서는 RMW에 적용한다고 범위를 정해요. 이름에 atomic이 있다고 모든 원자 함수의 범용 장벽으로 바꿔 쓰면 안 돼요.'), ('장벽과 RMW 사이에 다른 메모리 접근을 끼우지 않는 것이 좋은 이유는 무엇인가요?', ['사이에 끼운 접근은 해당 장벽의 보강 약속에 포함되지 않기 때문이에요', '사이에 접근을 넣으면 숫자 칸의 비트 수가 바뀌기 때문이에요'], '정답은 첫 번째예요. 순서 약속이 어디에 적용되는지가 이유예요. 숫자 칸의 크기와는 관계없어요. 그래서 관련 장벽을 RMW 바로 옆에 두는 배치를 권해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_386.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
